KG42.register("edges-8e1502b092ed203aae72b657",{"id":"S-fe8bfc4a9832e90a","source":"COMP-f0015e75a5829a38","type":"precedes","target":"COMP-aa22fdcebf0da947","evidence_class":"S","scientific_acceptance":false,"relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"paper_ids":["01-central_pool"],"assertions":[{"id":"01-central_pool::v141-c-R003::E::v141-c-R003-E001","paper":"01-central_pool","rule_id":"v141-c-R003","rule_ref":"01-central_pool::v141-c-R003","record":{"edge_id":"v141-c-R003-E001","source":"clearing.local","target":"coordination.local_operator","type":"precedes","constraint_ids":["v141-c-R003-C001"],"evidence_ids":["v141-b-g01-e001","v141-b-g02-E23"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R003-C001"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"COMP-f0015e75a5829a38","target":"COMP-aa22fdcebf0da947","source_occurrence_id":"01-central_pool::v141-c-R003::V::clearing.local","target_occurrence_id":"01-central_pool::v141-c-R003::V::coordination.local_operator","source_unit_id":"01-central_pool::v141-a-M01::clearing.local","target_unit_id":"01-central_pool::v141-a-M01::coordination.local_operator","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Computational solution of the proposed bilevel model using the cascade of two linear programs. | Governance of the community microgrid operator. | Operator remuneration through fees paid by community entities in the internal local market. | The proposed upper-level reserve and peak-power sharing policy for all community entities and time periods. | Upper-level profit sharing across all entities in the proposed community microgrid model.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e001","v141-b-g01-e007","v141-b-g02-E15","v141-b-g02-E18","v141-b-g02-E20","v141-b-g02-E21","v141-b-g02-E22","v141-b-g02-E23","v141-b-g02-E24"]},"active":true,"source_signature":"99ba5bb376a3ad5c746b8e4e50f857217e65f99427d8d06faab6c19b86f2c22b","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M01","source_definition":"Community member assets and internal/external exchanges are selected jointly in a common optimization problem with internal exchange conservation. Central versus distributed solution does not change this minimal allocation principle.","target_definition":"A common operator has lower dispatch coordination, contracts, fee remuneration and upper non-deterioration benefit-sharing roles; retain role branches.","constraints":[{"constraint_id":"v141-c-R003-C001","kind":"procedural","role":"core","statement":"Local market clearing is solved before the upper-level problem representing the community microgrid operator. Scope: Computational solution of the proposed bilevel model using the cascade of two linear programs. Condition: The lower-level market-clearing solution is unique and the stated cascade solution method is used.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.local","coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e001","v141-b-g02-E23"]}],"evidence":[{"evidence_id":"v141-b-g01-e001","location":{"location_id":"src-13c261d954-p01-c2r2__v141-a-M01-participation","page":1,"printed_page":null,"section":"Abstract","anchor_text":"T lettib, Antonio Giannitrapanib, Italy ext of community microgrids, where members of a community ca","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"A market-oriented pricing of energy exchanges within the community is obtained by implementing an internal local market based on the marginal pricing scheme. The market aims at maximizing the social welfare of the community, thanks to the more efficient allocation of resources, the reduction of the peak power to be paid, and the increased amount of reserve, achieved at an aggregate level. A community microgrid operator, acting as a benevolent planner, redistributes revenues and costs among the members, in such a way that the solution achieved by each member within the community is not worse than the solution it would achieve by acting individually. In this way, each member is incentivized to participate in the community on a voluntary basis. The overall framework is formulated in the form of a bilevel model, where the lower level problem clears the market, while the upper level problem plays the role of the community microgrid operator."},{"evidence_id":"v141-b-g02-E23","location":{"location_id":"src-13c261d954-p07-c1r3__v141-a-M01-validation","page":7,"printed_page":null,"section":"3.2","anchor_text":"defined. 4. Summarizing, in the proposed formulation, the upper level problem (1) is an optimization","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"definition"},"source_text":"In the proposed bilevel formulation, the lower level problem is a linear program which does not depend on the decision variables of the upper level problem. Moreover, for a fixed solution of the lower level problem, the upper level problem is also a linear program. This implies that, if the solution of the lower level problem is unique, the bilevel model can be solved very efficiently as the cascade of two linear programs, one corresponding to the lower level, and the other corresponding to the upper level. Notice that uniqueness of the solution of the lower level problem can be checked a priori via standard tools in linear programming [34]. If the lower level solution is not unique, the bilevel problem can be tackled by recasting it as a single optimization program. The resulting model is nonlinear, due to the bilinear terms π_{u,t}^com e_{u,t}^com and π_{u,t}^com i_{u,t}^com appearing in (27)."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Computational solution of the proposed bilevel model using the cascade of two linear programs. | Governance of the community microgrid operator. | Operator remuneration through fees paid by community entities in the internal local market. | The proposed upper-level reserve and peak-power sharing policy for all community entities and time periods. | Upper-level profit sharing across all entities in the proposed community microgrid model.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e001","v141-b-g01-e007","v141-b-g02-E15","v141-b-g02-E18","v141-b-g02-E20","v141-b-g02-E21","v141-b-g02-E22","v141-b-g02-E23","v141-b-g02-E24"]},"source_record":{"edge_id":"v141-c-R003-E001","source":"clearing.local","target":"coordination.local_operator","type":"precedes","constraint_ids":["v141-c-R003-C001"],"evidence_ids":["v141-b-g01-e001","v141-b-g02-E23"]},"paper_scope_note":"Operational responsibilities, lower-level clearing output, energy valuation, fees, and upper-level sharing are kept separate; the price equation retains import/export and complementary slackness conditions. The ordering of the two-level LP is limited only to the unique-solution and cascaded-solution branches."}}],"assertion_ids":["01-central_pool::v141-c-R003::E::v141-c-R003-E001"]});
